#![no_std]

#[derive(Debug, Clone, Copy)]
pub struct PidController {
    // معاملات الضبط (Tuning Gains):
    pub kp: f32, // معامل التناسب
    pub ki: f32, // معامل التكامل
    pub kd: f32, // معامل التفاضل

    // حدود الخرج (Output Limits لمنع تشبع المحرك):
    pub min_output: f32,
    pub max_output: f32,

    // الحالة الداخلية (State):
    integral: f32,
    prev_error: f32,
}

impl PidController {
    pub const fn new(kp: f32, ki: f32, kd: f32, min_output: f32, max_output: f32) -> Self {
        Self {
            kp,
            ki,
            kd,
            min_output,
            max_output,
            integral: 0.0,
            prev_error: 0.0,
        }
    }

    pub fn update(&mut self, setpoint: f32, current_value: f32, dt: f32) -> f32 {
        if dt <= 0.0 {
            return 0.0;
        }

        // 1. حساب الخطأ الحالي (Error):
        let error = setpoint - current_value;

        // 2. حساب الحد التناسبي (P Term):
        let p_term = self.kp * error;

        // 3. حساب الحد التكاملي مع حماية Integral Windup (I Term):
        self.integral += error * dt;
        let i_term = self.ki * self.integral;

        // 4. حساب الحد التفاضلي لمنع التذبذب والاصطدام (D Term):
        let derivative = (error - self.prev_error) / dt;
        let d_term = self.kd * derivative;

        self.prev_error = error;

        // 5. حساب الخرج الكلي وقصه داخل الحدود الآمنة:
        let total_output = p_term + i_term + d_term;

        if total_output > self.max_output {
            self.max_output
        } else if total_output < self.min_output {
            self.min_output
        } else {
            total_output
        }
    }

    pub fn reset(&mut self) {
        self.integral = 0.0;
        self.prev_error = 0.0;
    }
}

